//! #7435: a jq program's operator chains and nesting are held to the native stack, not to 256 levels.
//! Each row's answer is jq 1.7.1's (`/usr/bin/jq`, the same in jq 1.8.2), or, where jq refuses for
//! a limit of its own C implementation (noted), the answer it gives below that limit. Generated by
//! `.ai/scratch/gen7435.py`.

use std::io::Write;

use anyhow::Result;

use crate::run_jq_full;

/// Runs `program` from a `-f` file (a long one is past the 128 KiB a single argument may be on Linux)
/// over `{"a":5}`.
fn run_program(program: &str) -> Result<(String, String, i32)> {
    let mut file = tempfile::NamedTempFile::new()?;
    file.write_all(program.as_bytes())?;
    let path = file.path().to_string_lossy().into_owned();
    run_jq_full(&["-c", "-f", &path], Some("{\"a\":5}"))
}

/// The program of `shape` at `n` operands or levels (the generator's `shapes7435.py`).
fn program(shape: &str, n: usize) -> String {
    let join =
        |sep: &str, item: &dyn Fn(usize) -> String| (0..n).map(item).collect::<Vec<_>>().join(sep);
    match shape {
        "or" => join(" or ", &|i| format!(".a == {i}")),
        "and" => join(" and ", &|_| "true".into()),
        "plus" => join(" + ", &|_| "1".into()),
        "minus" => join(" - ", &|_| "1".into()),
        "times" => join(" * ", &|_| "1".into()),
        "alt" => format!("{} // 1", join(" // ", &|_| "null".into())),
        "question" => format!(".a{}", "?".repeat(n)),
        "brackets" => format!("{}1{} | [..] | length", "[".repeat(n), "]".repeat(n)),
        "parens" => format!("{}1{}", "(".repeat(n), ")".repeat(n)),
        "objs" => format!("{}1{} | [paths] | length", "{a:".repeat(n), "}".repeat(n)),
        "trys" => format!("{}1", "try ".repeat(n)),
        "labels" => format!("{}1", "label $a | ".repeat(n)),
        "reduce" => format!("{}0{}", "reduce 1 as $x (".repeat(n), "; .)".repeat(n)),
        "interp" => format!("{}1{} | length", "\"\\(".repeat(n), ")\"".repeat(n)),
        "negs" => format!("{}1", "- ".repeat(n)),
        "ifs" => format!("{}1{}", "if true then ".repeat(n), " else 0 end".repeat(n)),
        "defs" => format!("1 | ({}7)", join("", &|i| format!("def f{i}: 1; "))),
        "or-select" => format!("select({})", join(" or ", &|i| format!(".a == {i}"))),
        "plus-def" => format!("def f: {}; f", join(" + ", &|_| "1".into())),
        "plus-nested" => {
            let half = |k: usize| vec!["1"; k].join(" + ");
            format!("({}) + {}", half(n / 2), half(n - n / 2))
        }
        _ => unreachable!("{shape}"),
    }
}

/// `(shape, operands or levels, answer, what jq 1.7.1 says instead when it refuses)`.
const ROWS: &[(&str, usize, &str, &str)] = &[
    ("or", 300, "true", ""),
    (
        "or",
        3000,
        "true",
        "jq: error: function compiled to 80985 bytes which is too lon",
    ),
    ("and", 300, "true", ""),
    ("and", 3000, "true", ""),
    ("plus", 300, "300", ""),
    ("plus", 3000, "3000", ""),
    ("minus", 300, "-298", ""),
    ("minus", 3000, "-2998", ""),
    ("times", 300, "1", ""),
    ("times", 3000, "1", ""),
    ("alt", 300, "1", ""),
    (
        "alt",
        3000,
        "1",
        "jq: error: function compiled to 87004 bytes which is too lon",
    ),
    ("question", 300, "5", ""),
    ("question", 3000, "5", ""),
    ("brackets", 300, "301", ""),
    ("brackets", 3000, "3001", ""),
    ("parens", 300, "1", ""),
    ("parens", 3000, "1", ""),
    ("objs", 300, "300", ""),
    ("objs", 3000, "3000", ""),
    ("trys", 300, "1", ""),
    ("trys", 3000, "1", ""),
    ("labels", 300, "1", ""),
    (
        "labels",
        3000,
        "1",
        "jq: error: function compiled to 102004 bytes which is too lo",
    ),
    ("reduce", 300, "0", ""),
    (
        "reduce",
        3000,
        "0",
        "jq: error: memory exhausted at <top-level>, line 1:",
    ),
    ("interp", 300, "1", ""),
    ("interp", 3000, "1", ""),
    ("negs", 300, "1", ""),
    ("negs", 3000, "1", ""),
    ("ifs", 300, "1", ""),
    ("ifs", 3000, "1", ""),
    ("defs", 300, "7", ""),
    ("defs", 3000, "7", ""),
    ("or-select", 300, "{\"a\":5}", ""),
    (
        "or-select",
        3000,
        "{\"a\":5}",
        "jq: error: function compiled to 80984 bytes which is too lon",
    ),
    ("plus-def", 300, "300", ""),
    ("plus-def", 3000, "3000", ""),
    ("plus-nested", 300, "300", ""),
    ("plus-nested", 3000, "3000", ""),
];

#[test]
fn chains_and_nesting_past_256_levels_run_as_in_jq_7435() -> Result<()> {
    for (shape, n, answer, _jq_refuses) in ROWS {
        let (out, err, code) = run_program(&program(shape, *n))?;
        assert_eq!(
            (out.trim_end(), code),
            (*answer, 0),
            "{shape} at {n}: {}",
            err.lines().next().unwrap_or_default()
        );
    }
    Ok(())
}

/// Far past what the stack holds, a program is refused as jq refuses one too deep for its parser, with
/// `memory exhausted` (exit 3), and never overflows the stack; 30,000 operands either answer or are
/// refused so, whatever the build.
#[test]
fn a_program_past_the_stack_is_refused_not_overflowed_7435() -> Result<()> {
    let refused = |out: &str, err: &str, code: i32| {
        out.is_empty() && code == 3 && err.starts_with("jq: error: memory exhausted at <top-level>")
    };
    for (shape, n) in [
        ("or", 30_000),
        ("plus", 30_000),
        ("question", 30_000),
        ("brackets", 30_000),
        ("parens", 30_000),
        ("negs", 30_000),
        ("defs", 30_000),
    ] {
        let (out, err, code) = run_program(&program(shape, n))?;
        let answered = code == 0 && !out.trim_end().is_empty();
        assert!(
            answered || refused(&out, &err, code),
            "{shape} at {n}: {code} {err}"
        );
    }
    for shape in ["plus", "parens"] {
        let (out, err, code) = run_program(&program(shape, 2_000_000))?;
        assert!(
            refused(&out, &err, code),
            "{shape} at 2,000,000: {code} {err}"
        );
    }
    Ok(())
}
